int foo(int a, double b, int c, int p){    
    a = a/p; 

    for (int i = 0; i < a; ++i){c = i + c;}

    for (int i = 0; i < a; ++i)        
        c = i + c;  

    for (int i = 0; i < a; ++i){
        c = i;  
    }  

    a = a + c; 
    return a;
}

void bar(double x, int T){
    for (int i = 0; i < T; ++i)
        for (int j = 0; j < T; ++j)
            x = j + 1;  
    for (int i = 0; i < T; ++i){
        for (int j = 0; j < T; ++j){
            for (int k = 0; k < T; ++k){
                x = j + k;  
